parameters.jsCode:
const body = $('Webhook Trigger').item.json.body || {};
const registry = $input.item.json.departments || $input.item.json || [];

if (!body.organization_id || !body.threadId) {
  return { json: { valid: false, reason: 'Thiếu thông tin thread_id hoặc organization_id' } };
}

let matchedDept = null;
if (body.departmentId) {
  matchedDept = registry.find(d => d.department_id === body.departmentId);
} else if (body.departmentName) {
  matchedDept = registry.find(d => d.department_name === body.departmentName);
}

if (!matchedDept) {
  return { json: { valid: false, reason: 'Department not found in registry (Phòng ban chưa được cấp phép)' } };
}

return { 
  json: { 
    valid: true, 
    threadId: body.threadId,
    organization_id: body.organization_id,
    body: body.body,
    departmentId: matchedDept.department_id, 
    departmentName: matchedDept.department_name 
  } 
};

